CREATE TABLE IF NOT EXISTS dispatch_cases(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,external_incident_id TEXT NOT NULL,priority INTEGER NOT NULL CHECK(priority BETWEEN 1 AND 5),payload JSONB NOT NULL,recommendation JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'received' CHECK(status IN('received','validated','recommendation_ready','manual_only','dispatcher_review','dispatched','cancelled')),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,dispatched_by TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS dispatch_case_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,case_id BIGINT NOT NULL REFERENCES dispatch_cases(id),actor_id TEXT NOT NULL,event_type TEXT NOT NULL,from_status TEXT,to_status TEXT,event_data JSONB NOT NULL DEFAULT '{}'::jsonb,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION reject_dispatch_event_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'dispatch history is append-only';END$$;DROP TRIGGER IF EXISTS dispatch_case_events_immutable ON dispatch_case_events;CREATE TRIGGER dispatch_case_events_immutable BEFORE UPDATE OR DELETE ON dispatch_case_events FOR EACH ROW EXECUTE FUNCTION reject_dispatch_event_mutation();CREATE INDEX IF NOT EXISTS dispatch_cases_tenant_status_idx ON dispatch_cases(tenant_id,status,updated_at DESC);

